import { fileURLToPath } from "node:url";
import Database from "better-sqlite3";
import { drizzle, type BetterSQLite3Database } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import * as schema from "./schema.ts";

export type Db = BetterSQLite3Database<typeof schema> & { $client: Database.Database };

/** SQL migrations generated by drizzle-kit (`pnpm --filter server db:generate`). */
export const MIGRATIONS_DIR = fileURLToPath(new URL("./migrations", import.meta.url));

/**
 * Opens (creating it if needed) the SQLite database at `file`, enables WAL mode and foreign
 * keys, and applies any migrations that have not run yet. Close with `db.$client.close()`.
 */
export function openDatabase(file: string): Db {
  const sqlite = new Database(file);
  try {
    sqlite.pragma("journal_mode = WAL");
    sqlite.pragma("foreign_keys = ON");
    const db = drizzle({ client: sqlite, schema });
    migrate(db, { migrationsFolder: MIGRATIONS_DIR });
    return db;
  } catch (error) {
    sqlite.close();
    throw error;
  }
}

export { schema };
